const i=new Intl.NumberFormat("vi-VN");function o(t){return t==null?"—":i.format(Math.round(t))+"đ"}function a(t){if(t==null||t===0)return"0";const r=Math.abs(t);if(r>=1e6){const e=t/1e6;return Number.isInteger(e)?`${e}M`:`${e.toFixed(1).replace(/\.0$/,"")}M`}return r>=1e3?`${Math.round(t/1e3)}K`:String(t)}function c(t){if(!t)return"—";const r=new Date(t);return isNaN(r.getTime())?t:r.toLocaleDateString("vi-VN",{year:"numeric",month:"2-digit",day:"2-digit"})}function s(t){if(!t)return"—";const r=new Date(t.includes(" ")?t.replace(" ","T"):t);return isNaN(r.getTime())?t:r.toLocaleString("vi-VN",{dateStyle:"short",timeStyle:"short"})}function f(t){return t?t.replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"').replace(/&#0?39;/g,"'").replace(/&nbsp;/g," "):""}function g(t){const r=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),n=String(t.getDate()).padStart(2,"0");return`${r}-${e}-${n}`}export{c as a,s as b,a as c,f as d,o as f,g as y};
